`,(0,r.jsx)(i.li,{children:'Click the "Share project" button to the right of the project name'}),`
`,(0,r.jsx)(i.li,{children:'Add individual members using their name or email, or copy and paste a list of email addresses for bulk sharing (in this case, the project will show up in their "Shared with you" section)'}),`
`,(0,r.jsx)(i.li,{children:'Or, share with "Everyone at [your organization]" to make your project discoverable within the Team tab'}),`
